using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- CalculateTotal: DataRow for inline combinations ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(25.00, 2, 0.10, 55.00, DisplayName = "Two items, 10% tax")]
    [DataRow(100.00, 1, 0.25, 125.00, DisplayName = "Single item, 25% tax")]
    [DataRow(0.00, 10, 0.10, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.05, 0.00, DisplayName = "Zero quantity")]
    [DataRow(19.99, 3, 1.0, 119.94, DisplayName = "100% tax")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- CalculateTotal: DynamicData with ValueTuples for invalid inputs ---

    [TestMethod]
    [DynamicData(nameof(InvalidCalculateTotalData))]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRange(
        decimal unitPrice, int quantity, decimal taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(unitPrice, quantity, taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    public static IEnumerable<(decimal unitPrice, int quantity, decimal taxRate, string expectedParam)>
        InvalidCalculateTotalData =>
    [
        (-1m, 1, 0.1m, "unitPrice"),
        (10m, -1, 0.1m, "quantity"),
        (10m, 1, -0.1m, "taxRate"),
        (10m, 1, 1.5m, "taxRate"),
    ];

    // --- ApplyDiscount: DataRow for common discount scenarios ---

    [TestMethod]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
    [DataRow(200.00, 25.0, 150.00, DisplayName = "25% off")]
    [DataRow(50.00, 0.0, 50.00, DisplayName = "No discount")]
    [DataRow(80.00, 100.0, 0.00, DisplayName = "100% discount (free)")]
    [DataRow(49.99, 50.0, 24.995, DisplayName = "Fractional result")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- ApplyDiscount: DynamicData with TestDataRow for invalid discounts ---

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData))]
    public void ApplyDiscount_WithInvalidPercent_ThrowsArgumentOutOfRange(
        decimal price, decimal discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }

    public static IEnumerable<TestDataRow<(decimal price, decimal discountPercent)>>
        InvalidDiscountData =>
    [
        new((100m, -1m))   { DisplayName = "Negative discount" },
        new((100m, 101m))  { DisplayName = "Discount over 100%" },
        new((50m, -0.01m)) { DisplayName = "Slightly negative" },
    ];
}

